const LocationForm = ({ locations, setLocations, findMeetingSpot }) => {
    const handleInputChange = (index, field, value) => {
        const updatedLocations = [...locations];
        updatedLocations[index][field] = parseFloat(value);
        setLocations(updatedLocations);
    };

    const addLocation = () => setLocations([...locations, { lat: "", lng: "" }]);

    return (
        <div>
            <h2>Enter Locations</h2>
            {locations.map((location, index) => (
                <div key={index}>
                    <input type="number" placeholder="Latitude" onChange={(e) => handleInputChange(index, "lat", e.target.value)} />
                    <input type="number" placeholder="Longitude" onChange={(e) => handleInputChange(index, "lng", e.target.value)} />
                </div>
            ))}
            <button onClick={addLocation}>+ Add Location</button>
            <button onClick={findMeetingSpot}>Find Meeting Spot</button>
        </div>
    );
};

export default LocationForm;
